const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to today's lecture on sustainable community living and repair practices.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.932833333333333},{"speaker":"A","text":"We will explore how fixing broken items instead of throwing them away helps our local environment.","position":2,"audioStartSeconds":6.132833333333333,"audioEndSeconds":12.25475},{"speaker":"A","text":"Consider a hypothetical village where residents started a monthly repair cafe last year.","position":3,"audioStartSeconds":12.45475,"audioEndSeconds":18.265416666666667},{"speaker":"A","text":"Local volunteers brought their broken electronics and torn clothing to the community hall.","position":4,"audioStartSeconds":18.465416666666666,"audioEndSeconds":24.098041666666667},{"speaker":"A","text":"Organisers noticed that electric kettles were the most common item brought in by residents.","position":5,"audioStartSeconds":24.298041666666666,"audioEndSeconds":30.097},{"speaker":"A","text":"Most of these small kitchen appliances only needed a simple new fuse to work again.","position":6,"audioStartSeconds":30.297,"audioEndSeconds":35.59341666666667},{"speaker":"A","text":"Besides saving money people learned valuable practical skills from experienced neighborhood mechanics.","position":7,"audioStartSeconds":35.793416666666666,"audioEndSeconds":42.12070833333333},{"speaker":"A","text":"Instead of replacing furniture people gathered wood scraps to build sturdy outdoor benches.","position":8,"audioStartSeconds":42.320708333333336,"audioEndSeconds":48.01658333333334},{"speaker":"A","text":"If someone needed help with sewing local tailors offered free advice every Saturday morning.","position":9,"audioStartSeconds":48.21658333333333,"audioEndSeconds":53.88670833333333},{"speaker":"A","text":"The local council measured success by weighing the total garbage sent to the landfill.","position":10,"audioStartSeconds":54.086708333333334,"audioEndSeconds":59.292875},{"speaker":"A","text":"They discovered that heavy waste decreased significantly after six months of community workshops.","position":11,"audioStartSeconds":59.492875,"audioEndSeconds":65.717125},{"speaker":"A","text":"Another major benefit was the reduction in plastic packaging purchased from distant superstores.","position":12,"audioStartSeconds":65.917125,"audioEndSeconds":71.93516666666666},{"speaker":"A","text":"When citizens shared tools they spent less overall cash on expensive garden equipment.","position":13,"audioStartSeconds":72.13516666666666,"audioEndSeconds":77.83104166666666},{"speaker":"A","text":"Future plans include launching a website where neighbors can easily borrow heavy ladders.","position":14,"audioStartSeconds":78.03104166666667,"audioEndSeconds":83.559375},{"speaker":"A","text":"Please remember that small daily choices make a massive difference for our planet.","position":15,"audioStartSeconds":83.759375,"audioEndSeconds":88.789125}],"questions":[{"prompt":"Main community event: ______ cafe","answer":"repair","evidenceSentence":3,"evidence":"repair cafe","explanation":"Bài giảng đề cập đến sự kiện cộng đồng là 'repair cafe'."},{"prompt":"Most common broken item: electric ______","answer":"kettles","evidenceSentence":5,"evidence":"electric kettles","explanation":"Ấm điện là món đồ phổ biến nhất được mang đến."},{"prompt":"Part needing replacement: new ______","answer":"fuse","evidenceSentence":6,"evidence":"new fuse","explanation":"Hầu hết các thiết bị chỉ cần một chiếc cầu chì mới."},{"prompt":"Material used for benches: wood ______","answer":"scraps","evidenceSentence":8,"evidence":"wood scraps","explanation":"Mọi người tận dụng những mảnh gỗ vụn để làm ghế."},{"prompt":"Council measurement method: weighing the total ______","answer":"garbage","evidenceSentence":10,"evidence":"total garbage","explanation":"Hội đồng đo lường thành công bằng cách cân tổng lượng rác thải."},{"prompt":"Future borrowing item: heavy ______","answer":"ladders","evidenceSentence":14,"evidence":"heavy ladders","explanation":"Kế hoạch tương lai bao gồm việc cho mượn những chiếc thang nặng."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
